(window.TIMELINE_TRANSLATIONS=window.TIMELINE_TRANSLATIONS||{})["eo"]={"qin-dynasty":{"id":"qin-dynasty","title":"Dinastio Qin","summary":"La ŝtato Qin konkeris siajn ĉefajn rivalojn sub Ying Zheng, kiu alprenis la imperian titolon Qin Shi Huang. La dinastio daŭris nur mallonge, sed ĝiaj militaj kaj administraj praktikoj influis la postan imperion Han.","began":"La konkeroj de Qin kulminis per unuigo, kaj Ying Zheng deklaris sin imperiestro.","ended":"La dinastio kolapsis en la jaroj post la morto de Qin Shi Huang; konkurantaj potencoj batalis, antaŭ ol Han starigis imperian regadon.","why":"Ĝi kreis imperian politikan kadron, kiun postaj dinastioj adaptis."},"confucius":{"id":"confucius","title":"Konfuceo instruas etikan regadon","summary":"Konfuceo instruis dum la periodo de Printempoj kaj Aŭtunoj. Li emfazis moralan konduton, familiajn respondecojn, lernadon kaj la devon de la reganto regi per virto. Liaj instruoj fariĝis grava intelekta tradicio, kaj postaj imperiaj registaroj metis konfuceajn tekstojn en la centron de la oficiala edukado.","why":"Liaj instruoj formis politikan etikon, edukadon kaj familiajn idealojn tra Orienta Azio."},"stonewall-riots":{"id":"stonewall-riots","title":"Ribelo de Stonewall","summary":"Klientoj kaj subtenantoj rezistis polican trudeniron en la Stonewall Inn en Novjorko, kaj sekvis pliaj konfrontoj kaj manifestacioj. La ribelo fariĝis potenca referencpunkto por kreskanta movado kontraŭ la persekutado de seksaj malplimultoj.","why":"Stonewall helpis vigligi la gejan liberigon kaj la postan GLBT-organizadon, kvankam ĝi ne estis la unua ago de rezisto."}};
